//! Current Python relay expiry oracle, generated by generate_expiry_parity.py.
use mycelium_mobile_core::{stage_node::StageNode, wire::{self, Activation}};
use serde_json::Value;

#[test]
fn current_python_expiry_decisions_and_bytes_match() {
    let fixture: Value = serde_json::from_str(include_str!("expiry_parity.json")).unwrap();
    let mut count = 0;
    for case in fixture["cases"].as_array().unwrap() {
        let mut node = StageNode::new("node-phone");
        for want in case["steps"].as_array().unwrap() {
            let frame = wire::decode_frame(&hex::decode(want["frame_hex"].as_str().unwrap()).unwrap()).unwrap();
            let got = node.on_frame_at(want["at"].as_f64().unwrap(), want["from"].as_str().unwrap(), &frame, &mut |path,hop,_| {
                let seq = if hop.phase == "PREFILL" { path.prompt_length } else { hop.position + 1 };
                let values: Vec<f32> = (0..seq*8).map(|i| 0.5*((i%17) as f32-8.0)/8.0).collect();
                Ok(Activation::from_flat_f32(seq,8,&values).encode().unwrap())
            });
            assert_eq!(got.ack, want["transport_ack"].as_bool().unwrap(), "{} {want}", case["name"]);
            if want.get("accepted").is_some() { assert_eq!(got.accepted,want["accepted"].as_bool()); }
            if want.get("disposition").is_some() {
                assert_eq!(got.disposition,want["disposition"].as_str(), "{} {want}",case["name"]);
                assert_eq!(got.reason,want["reason"].as_str().unwrap());
                assert_eq!(got.executed, want["executed"] == 1);
            }
            let sends=want["sends"].as_array().unwrap();
            assert_eq!(got.sends.len(),sends.len());
            for (got,want) in got.sends.iter().zip(sends) {
                assert_eq!(got.frame,hex::decode(want["frame_hex"].as_str().unwrap()).unwrap());
                assert_eq!(got.to,want["to"].as_str().unwrap());
            }
            node.drain_expired_releases();
            count += 1;
        }
    }
    assert!(count >= 20);
}
